window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-15191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβήτωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 3952 na letra ε · nº geral 15191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que sobe em (cavalo, navio), gen. 2 que jorra 3 que se lança para 4 dominador; senhor de 5 hábil em; perito ♦ ὁ ἐπιβήτωρ 6 cavaleiro 7 passageiro de navio. 〈ἐπιβαίνω〉</p></section></article>\n<article id=\"entry-dgp-15192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβιβάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3953 na letra ε · nº geral 15192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer subir em; fazer embarcar.</p></section></article>\n<article id=\"entry-dgp-15193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3954 na letra ε · nº geral 15193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. ind. e aor.2 ἐπεβίων) 1 viver de, gen. 2 sobreviver.</p></section></article>\n<article id=\"entry-dgp-15194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβλαστάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3955 na letra ε · nº geral 15194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brotar sobre, dat. 2 germinar em seguida ou além 3 crescer.</p></section></article>\n<article id=\"entry-dgp-15195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβλέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 3956 na letra ε · nº geral 15195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 voltar o olhar para; olhar; prestar atenção em, ac., εἰς ou ἐπί ou, πρός e ac. 2 examinar; observar 3 olhar com inveja; invejar, dat.</p></section></article>\n<article id=\"entry-dgp-15196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίβλεψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3957 na letra ε · nº geral 15196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de olhar; olhada 2 consideração; exame; observação. 〈ἐπιβλέπω〉</p></section></article>\n<article id=\"entry-dgp-15197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίβλημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3958 na letra ε · nº geral 15197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tampa 2 colcha; tapete 3 manto 4 remendo em manto. 〈ἐπιβάλλω〉</p></section></article>\n<article id=\"entry-dgp-15198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβλής, ῆτος (ό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3959 na letra ε · nº geral 15198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trave; ferrolho. 〈ἐπιβάλλω〉</p></section></article>\n<article id=\"entry-dgp-15199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβλώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 3960 na letra ε · nº geral 15199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(2ª sing. aor.2 ἐπέμολε) sobrevir; chegar.</p></section></article>\n<article id=\"entry-dgp-15200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβοάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3961 na letra ε · nº geral 15200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπιβοήσομαι, jôn. ἐπιβώσομαι, aor. ἐπεβόησα, jôn. 3a pl. ἐπεβώσαντο) 1 soltar gritos 2 gritar para alguém, dat., que, or. conj. (ὅτι); gritar para que, inf.: τίς Ἄγιδι ἐπεβοήσεν tuc. alguém gritou para Ágis, ἐκείνῳ ἐπιβοῶν πλεῖν tuc. gritando-lhe que se pusesse a navegar 3 entoar (canto, lamento): πτέρν᾽ ἄρασσε κἀπιβόα τὸ Μύσιον ésql. fere teu peito e entoa o canto mísio ♦ méd. 4 chamar aos gritos; clamar; invocar; chamar em socorro, ac.: θεοὺς ἐπιβώσομαι hom. invocarei os deuses, τὴν ἄλλην στρατιὴν ἐπεβώσαντο her. chamaram em socorro o restante da tropa 5 ir gritando: Θουκυδίδου ἐπιβοωμένου μὴ ἐφεδρευόντων ἐγγὺς τῶν πολεμίων ἀπολέσαι τὴν πατρίδα tuc. Tucídides ia gritando que, estando os inimigos à espreita, não causassem a ruína da pátria 6 aplaudir.</p></section></article>\n<article id=\"entry-dgp-15201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβοήθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3962 na letra ε · nº geral 15201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">socorro. 〈ἐπιβοηθέω〉</p></section></article>\n<article id=\"entry-dgp-15202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβοηθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3963 na letra ε · nº geral 15202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vir em socorro de, dat. 2 vir em auxílio contra alguém, ἐπί e ac.</p></section></article>\n<article id=\"entry-dgp-15203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβόημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3964 na letra ε · nº geral 15203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">clamor; grito; invocação. 〈ἐπιβοάω〉</p></section></article>\n<article id=\"entry-dgp-15204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβόησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3965 na letra ε · nº geral 15204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aclamação; clamor; aplauso. 〈ἐπιβοάω〉</p></section></article>\n<article id=\"entry-dgp-15205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβόητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3966 na letra ε · nº geral 15205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 célebre; famoso 2 mal conceituado; difamado. 〈ἐπιβοάω〉</p></section></article>\n<article id=\"entry-dgp-15206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβολή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3967 na letra ε · nº geral 15206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de lançar ou de pôr sobre; ação de vestir algo, gen.; lançamento de, gen. 2 aplicação; aposição de, gen. 3 sobreposição 4 irrupção; invasão; ataque 5 imposto; penalidade; multa 6 empresa; projeto: ἐξ ἐπιβολῆς de propósito; de caso pensado; deliberadamente. 〈ἐπιβάλλω〉</p></section></article>\n<article id=\"entry-dgp-15207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβομβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3968 na letra ε · nº geral 15207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer ouvir um barulho que retine sobre, dat. 2 zumbir 3 fazer ressoar.</p></section></article>\n<article id=\"entry-dgp-15208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβουκόλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3969 na letra ε · nº geral 15208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">boieiro.</p></section></article>\n<article id=\"entry-dgp-15209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβούλευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3970 na letra ε · nº geral 15209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">maquinação; projeto hostil; cilada. 〈ἐπιβουλεύω〉</p></section></article>\n<article id=\"entry-dgp-15210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβουλευτής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 3971 na letra ε · nº geral 15210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que trama ciladas. 〈ἐπιβουλεύω〉</p></section></article>\n<article id=\"entry-dgp-15211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβουλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 3972 na letra ε · nº geral 15211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 projetar; tramar algo, ac., contra alguém, dat. 2 conspirar contra, dat. 3 projetar; ter a intenção de, inf. ou or. conj. (ὅπως) ♦ méd. 4 tramar; conspirar ♦ pas. 5 (pessoa) ser alvo de complô 6 (coisa) ser planejado contra, dat. 〈ἐπί, βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-15212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβουλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3973 na letra ε · nº geral 15212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 projeto: μετά ou ἐξ ἐπιβουλῆς com premeditação 2 maquinação; conspiração: τῇ ἐπιβουλῇ ou ἐξ ἐπιβουλῆς ou μετ᾽ ἐπιβουλῆς deliberadamente, traiçoeiramente. 〈ἐπί, βουλή〉</p></section></article>\n<article id=\"entry-dgp-15213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίβουλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3974 na letra ε · nº geral 15213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que prepara armadilhas; ardiloso; traiçoeiro (pessoa) 2 cheio de emboscadas; insidioso; perigoso (coisa). 〈ἐπί, βουλή〉</p></section></article>\n<article id=\"entry-dgp-15214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβούλως</h1><div class=\"entry-meta\"><span>DGP · ordem 3975 na letra ε · nº geral 15214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. insidiosamente; traiçoeiramente.</p></section></article>\n<article id=\"entry-dgp-15215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβραβεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 3976 na letra ε · nº geral 15215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atribuir; outorgar.</p></section></article>\n<article id=\"entry-dgp-15216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβραδύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3977 na letra ε · nº geral 15216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tardar; atrasar-se.</p></section></article>\n<article id=\"entry-dgp-15217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβρέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 3978 na letra ε · nº geral 15217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐπέβρεμον) 1 fazer mugir 2 fazer bramir 3 fazer ressoar ♦ at. intr. e méd. 4 bramir 5 repercutir; ressoar.</p></section></article>\n<article id=\"entry-dgp-15218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβριθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3979 na letra ε · nº geral 15218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pesado; difícil de suportar; opressivo. 〈ἐπιβρίθω〉</p></section></article>\n<article id=\"entry-dgp-15219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβρίθω</h1><div class=\"entry-meta\"><span>DGP · ordem 3980 na letra ε · nº geral 15219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pesar sobre; pesar; ser opressivo 2 cair sobre; desmoronar 3 fincar 4 apoiar.</p></section></article>\n<article id=\"entry-dgp-15220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβροντάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3981 na letra ε · nº geral 15220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">troar em resposta.</p></section></article>\n<article id=\"entry-dgp-15221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβρόντητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3982 na letra ε · nº geral 15221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">como que atingido pelo raio; desvairado; aturdido. 〈ἐπιβροντάω〉</p></section></article>\n<article id=\"entry-dgp-15222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβύστρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3983 na letra ε · nº geral 15222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rolha; tampa. 〈ἐπιβύω〉</p></section></article>\n<article id=\"entry-dgp-15223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβύω</h1><div class=\"entry-meta\"><span>DGP · ordem 3984 na letra ε · nº geral 15223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tapar ♦ méd. 2 fechar: ἐπ. τὰ ὦτα luc. tapar as próprias orelhas.</p></section></article>\n<article id=\"entry-dgp-15224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβωθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 3985 na letra ε · nº geral 15224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐπιβοηθέω.</p></section></article>\n<article id=\"entry-dgp-15225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβώσασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3986 na letra ε · nº geral 15225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. méd. jôn. de ἐπιβοάω.</p></section></article>\n<article id=\"entry-dgp-15226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβώσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3987 na letra ε · nº geral 15226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de ἐπιβοάω.</p></section></article>\n<article id=\"entry-dgp-15227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβώσωνθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3988 na letra ε · nº geral 15227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. subj. aor. méd. jôn. de ἐπιβοάω.</p></section></article>\n<article id=\"entry-dgp-15228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιβώτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3989 na letra ε · nº geral 15228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardador de rebanho; pastor. 〈ἐπί, βώτωρ〉</p></section></article>\n<article id=\"entry-dgp-15229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγαιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3990 na letra ε · nº geral 15229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está sobre o solo; que se apóia sobre o solo. 〈ἐπί, γαῖα〉</p></section></article>\n<article id=\"entry-dgp-15230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγαμβρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 3991 na letra ε · nº geral 15230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 ser genro de, dat. 2 entrar como genro em uma família 3 casar com uma cunhada (viúva do irmão). 〈ἐπί, γαμβρός〉</p></section></article>\n<article id=\"entry-dgp-15231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγαμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3992 na letra ε · nº geral 15231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desposar em segundas núpcias; desposar em seguida 2 dar uma madrasta a, dat.</p></section></article>\n<article id=\"entry-dgp-15232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγαμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3993 na letra ε · nº geral 15232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 segundas núpcias 2 direito de casamento entre cidadãos e cidadãs de cidades diferentes 3 vínculo; parentesco por casamento. 〈ἐπίγαμος〉</p></section></article>\n<article id=\"entry-dgp-15233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγαμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3994 na letra ε · nº geral 15233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(homem) em idade de casar; (mulher) núbil. 〈ἐπί, γαμος〉</p></section></article>\n<article id=\"entry-dgp-15234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγάστριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3995 na letra ε · nº geral 15234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é submisso ao próprio ventre; guloso; glutão ♦ τὸ ἐπιγάστριον 2 epigástrio, região do abdômen. 〈ἐπί, γαστήρ〉</p></section></article>\n<article id=\"entry-dgp-15235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγαυρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3996 na letra ε · nº geral 15235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar orgulhoso ♦ méd. pas. 2 ser orgulhoso de; gloriar-se de, dat.</p></section></article>\n<article id=\"entry-dgp-15236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3997 na letra ε · nº geral 15236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vive sobre a terra 2 que se arrasta na terra; rasteiro (planta). 〈ἐπί, γῆ〉</p></section></article>\n<article id=\"entry-dgp-15237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγελάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3998 na letra ε · nº geral 15237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rir, sorrir 2 rir de; zombar de, dat.</p></section></article>\n<article id=\"entry-dgp-15238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγεννάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3999 na letra ε · nº geral 15238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 produzir em seguida ou em acréscimo ♦ pas. 2 crescer em seguida.</p></section></article>\n<article id=\"entry-dgp-15239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγέννημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4000 na letra ε · nº geral 15239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rebento; produto 2 Filos. resultado; conseqüência 3 Medic. sintoma. 〈ἐπιγεννάω〉</p></section></article>\n<article id=\"entry-dgp-15240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγεραίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 4001 na letra ε · nº geral 15240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">honrar; cobrir com honrarias.</p></section></article>\n<article id=\"entry-dgp-15241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4002 na letra ε · nº geral 15241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saborear; provar, gen.</p></section></article>\n<article id=\"entry-dgp-15242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγηθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4003 na letra ε · nº geral 15242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alegrar-se com, dat.</p></section></article>\n<article id=\"entry-dgp-15243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγίγνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4004 na letra ε · nº geral 15243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπιγενήσομαι) 1 nascer depois; produzir-se em seguida, na seqüência de, dat. ou ἐπί e dat.: οἱ ἐπιγενόμενοι τούτῳ σοφισταί her. os sábios que vieram depois dele, οἱ ἐπιγινόμενοι ἄνθρωποι hom. a posteridade, τῇ ἐπιγιγνομένῃ ἡμέρᾳ tuc. no dia seguinte 2 vir acrescentar-se a, dat. ou πρός e ac.; vir como conseqüência de: βουλαῖς οὐκ ἐπεγένετο τέλος teóg. às decisões não se seguiu a realização, ἅμα τῇ βροντῇ σεισμὸν ἐπιγένεσθαι her. ao trovão veio juntar-se, ao mesmo tempo, um tremor de terra 3 produzir-se subitamente; sobrevir, dat. ou ἐπί e dat.: πλώουσι αὐτοῖς ἐπεγένετο χειμών her. enquanto navegavam, sobreveio-lhes uma tempestade, εἰ ἄνεμος ἐπεγένετο τῇ φλογί tuc. se um vento viesse de repente sobre a chama, ἐπὶ δὲ τῇ ναυμαχίῃ ἐπεγένετο Ἱστίαιος her. no fim da batalha naval sobreveio Histieu [para atacar] 4 vir em seguida, em acréscimo a, dat. ou πρός e ac.: τὰ ἐπιγιγνόμενα artt. os juros acumulados de capital 5 vencer um prazo; chegar no prazo estipulado: ἐπιγιγνομένα τὰς μισθώσεις artt. os salários que vêm no prazo fixado.</p></section></article>\n<article id=\"entry-dgp-15244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγιγνώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 4005 na letra ε · nº geral 15244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπιγνώσομαι etc.) 1 reconhecer alguém, ac., a partir de algo, dat.: ὅπως μήτηρ σε μὴ ᾽πιγνώσεται φαιδρῷ προσώπῳ sóf. para que a mãe não te reconheça pelo rosto radiante, πατρὸς πειρήσομαι ἡμετέροιο αἲ κέ μ᾽ ἐπιγνώῃ hom. vou pôr nosso pai à prova para ver se me reconhece 2 observar; testemunhar, ac. ou part. pred.: ἵνα πάντες ἐπιγνώωσι μαρναμένους hom. para que todos vós os observeis a combater 3 reconhecer; constatar; compreender: ἐπιγνοίης ἂν [τὴν σοφίαν] οἰκείαν γενομένην; plat. reconhecerias [a sabedoria] se fosse ela a tua?, τὸν πόλεμον ἐπ. τίνα φύσιν ἔχει pol. compreender que natureza a guerra tem 4 ter noção de algo, gen. 5 chegar a uma decisão; decidir algo, ac. ou inf., a respeito de alguém, περί e gen.: εἰ δὲ περὶ ἡμῶν ἐπιγνώσεσθε μὴ τὰ εἰκότα tuc. se a nosso respeito não tomais as decisões plausíveis, οὐ τὰ πρόσφορα τοῖς οἰχομένοις ἐπιγιγνώσκοντες tuc. não decidindo (fornecer) aos soldados que partiam os meios de que necessitavam, ἐπ. τι εἶναί τινος d.h. decidir que algo pertence a alguém 6 tard. reconhecer; aprovar; admitir: ἐπιγνώσκετε οὖν τοὺς τοιούτους n.t. aprovai, portanto, os que têm tais qualidades.</p></section></article>\n<article id=\"entry-dgp-15245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4006 na letra ε · nº geral 15245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐπιγίγνομαι.</p></section></article>\n<article id=\"entry-dgp-15246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγλωσσάομαι,</h1><div class=\"entry-meta\"><span>DGP · ordem 4007 na letra ε · nº geral 15246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ωττάομαι-ῶμαι 1 proferir injúrias, insultos contra alguém, gen. 2 falar mal de alguém, περί e gen. 〈ἐπι, γλῶσσα〉</p></section></article>\n<article id=\"entry-dgp-15247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγνάμπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 4008 na letra ε · nº geral 15247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 curvar; dobrar 2 fazer ceder; convencer ♦ pas. 3 curvar-se, dobrar-se.</p></section></article>\n<article id=\"entry-dgp-15248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγνάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 4009 na letra ε · nº geral 15248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">limpar; renovar.</p></section></article>\n<article id=\"entry-dgp-15249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγνώμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4010 na letra ε · nº geral 15249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 capaz de decidir sobre; juiz; árbitro 2 conhecedor; entendido de, gen. 3 que perdoa, dat. 〈ἐπιγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-15250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγνωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4011 na letra ε · nº geral 15250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de reconhecer 2 conhecimento prático; conhecimento 3 exame; estudo. 〈ἐπιγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-15251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγονή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4012 na letra ε · nº geral 15251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 crescimento; progresso 2 descendência; geração. 〈ἐπιγίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-15252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4013 na letra ε · nº geral 15252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 descendente 2 Medic. nascido depois; que nasce por superfetação 3 que vem depois; que se junta a ♦ οἱ Ἐπίγονοι 4 os Epígonos, descendentes dos sete de Tebas, ou dos sucessores de Alexandre o Grande 5 a posteridade 6 favo de abelha. 〈ἐπιγίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-15253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγουνίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4014 na letra ε · nº geral 15253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coxa. 〈ἐπί, γόνυ〉</p></section></article>\n<article id=\"entry-dgp-15254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγράβδην</h1><div class=\"entry-meta\"><span>DGP · ordem 4015 na letra ε · nº geral 15254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 arranhando 2 riscando. 〈ἐπιγράφω〉</p></section></article>\n<article id=\"entry-dgp-15255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγραμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4016 na letra ε · nº geral 15255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inscrição em monumento, em obra de arte, em oferenda 2 pequena composição em verso; epigrama 3 título de obra 4 título honorífico 5 reclamação por escrito; pedido de punição; pedido de restituição. 〈ἐπιγράφω〉</p></section></article>\n<article id=\"entry-dgp-15256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγραμμάτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4017 na letra ε · nº geral 15256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena composição em dísticos; pequeno epigrama. 〈ἐπίγραμμα〉</p></section></article>\n<article id=\"entry-dgp-15257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγραφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4018 na letra ε · nº geral 15257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inscrição (em pedra, estátua) 2 registro (dos nomes e bens dos cidadãos) 3 contribuição paga pelos cidadãos inscritos 4 título de obra 5 título honorífico. 〈ἐπιγράφω〉</p></section></article>\n<article id=\"entry-dgp-15258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιγράφω</h1><div class=\"entry-meta\"><span>DGP · ordem 4019 na letra ε · nº geral 15258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 marcar ligeiramente; arranhar; esfolar levemente; entalhar: ὀϊστὸς ἐπέγραψε χρόα φωτός hom. a flecha esfolou a pele do homem, ἄκροις δακτύλοις ἐπιγράφειν luc. arranhar com a ponta dos dedos ♦ após hom. 2 escrever em; inscrever; gravar: ἐπ. ὀνομαστὶ τὰς πόλεις tuc. inscrever as cidades pelos nomes, αὐτοῦ ποιήματα ἐπέγραψεν plat. aí gravou seus poemas 3 escrever o nome; assinar: ἐπ. τὸν Ἀντοώνιον ap. assinar o nome de Antonio 4 entitular 5 Jur. inscrever ou fazer inscrever (em proposta de lei, em recurso na justiça), fazer inscrever (como penalidade), fixar como punição: τί δῆτά σοι τίμημ᾽ ἐπιγράψω τῇ δίκῃ; ar. que penalidade devo fixar contra ti neste processo? μέχρι πέντε δραχμῶν καθ᾽ ἕκαστον ἀδίκημα ἐπ. ésqn. estabelecer até cinco dracmas para cada infração cometida, τὰ ἐπιγεγραμμένα dem. a penalidade reclamada 6 Jur. inscrever (em lista, em registro de contribuição); registrar; com ἑαυτόν fazer-se inscrever: ἑμαυτῷ ἐπέγραψα τὴν μεγίστην εἰσφοράν isócr. inscrevi por minha própria conta a maior contribuição, ἐπιγράψαι σφᾶς αὐτοὺς ἐπιτρόπους is. inscrever-se a si mesmos como tutores, ἐπ. στρατιωτῶν καταλόγους plut. inscrever listas de soldados 7 estabelecer taxas, impostos ♦ méd. 8 fazer inscrever; fazer gravar para si: μεγάλην ἐπεγράφου τὴν Γοργόνα ar. fizeste gravar (como insígnia) a grande Górgona, κλητῆρ᾽ οὐδ᾽ ὁντινοῦν ἐπιγραψάμενος dem. sem ter feito com que fosse inscrita nenhuma testemunha da citação 9 aderir a: οἱ τὸν Πλάτωνα ἐπιγραφόμενοι luc. os adeptos de Platão, i.e., os platonistas 10 assumir a responsabilidade de; reclamar; reivindicar: algo, ἐπί e ac. ou dat.: ἐπιγράψαι ἀλλοτρίοις ἑαυτὸν πόνοις 11 atribuir a alguém, ac.: Ὅμηρον ἐπιγράφεσθαι luc. atribuir a Homero, ἐπ. τὴν αὑτοῦ προσηγορίαν plut. atribuir a própria denominação 12 inscrever em documento público: προστάτην ἐπιγράφεσθαι ar. inscrever como seu patrão, ἐπεγράψαντο πολίταις tuc. inscreveram como cidadãos 13 requerer uma multa ♦ pas. 14 tard. ser inscrito depois: αἱ ἐπιγραφεῖσα διαθῆκαι jos. as disposições inscritas.</p></section></article>\n<article id=\"entry-dgp-15259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίγρυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4020 na letra ε · nº geral 15259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ligeiramente curvo; um tanto adunco.</p></section></article>\n<article id=\"entry-dgp-15260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδακρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 4021 na letra ε · nº geral 15260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chorar; chorar em seguida; chorar por, dat.</p></section></article>\n<article id=\"entry-dgp-15261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδαμος</h1><div class=\"entry-meta\"><span>DGP · ordem 4022 na letra ε · nº geral 15261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἐπίδημος.</p></section></article>\n<article id=\"entry-dgp-15262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδανείζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4023 na letra ε · nº geral 15262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contrair uma segunda hipoteca ♦ méd. 2 obter empréstimo de novo (com bem já hipotecado). ᾽Επιδαύριος, α, ον 1 de Epidauro ♦ οἱ Ἑπιδαύριοι 2 o povo de Epidauro ♦ ἡ Ἐπιδαυρία 3 Epidáuria, região de Epidauro, na Argólida. 〈 Ἐπίδαυρος〉 ᾽Επίδαυρος, ου (ἡ) Epidauro, cidade da Argólida ou da Lacônia.</p></section></article>\n<article id=\"entry-dgp-15263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδαψιλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 4024 na letra ε · nº geral 15263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abundar ♦ méd. 2 dar em abundância, generosamente; prodigalizar, algo, ac., a alguém, dat. 3 dar com liberalidade; ser generoso, pródigo 4 Ret. (estilo) ser prolixo. 〈ἐπί, δαψιλής〉</p></section></article>\n<article id=\"entry-dgp-15264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέδρομα</h1><div class=\"entry-meta\"><span>DGP · ordem 4025 na letra ε · nº geral 15264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de ἐπιτρέχω.</p></section></article>\n<article id=\"entry-dgp-15265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4026 na letra ε · nº geral 15265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">necessitado; desprovido de, dat. 〈ἐπιδέομαι〉</p></section></article>\n<article id=\"entry-dgp-15266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδειγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4027 na letra ε · nº geral 15266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">marca; prova; exemplo. 〈ἐπιδείκνυμι〉</p></section></article>\n<article id=\"entry-dgp-15267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδείκνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 4028 na letra ε · nº geral 15267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπιδείξω) 1 mostrar abertamente; exibir algo, ac., a alguém, dat.: ἐπ. πᾶσαν τὴν Ἑλλάδα τοῖσι Πέρσῃσι her. mostrar a Grécia inteira aos persas, ἐπιδεῖξαι τὸ στράτευμα αὐτῇ xen. exibir o exército para ela [a rainha Cilissa] ♦ at. e méd. 2 demonstrar; explicar a alguém, dat., algo, ac., or. conj. (ὡς, ὅτι), or. inf., part.: ἐπιδείξω τὸν ἀλεκτρύον᾽ ὡς ἐτυράννει ar. demostrarei que o galo era senhor, ἐπιδεῖξαι σὺ μὲν χρηστός... εἶναι, ἐκεῖνος δὲ φαῦλος xen. demonstrar que tu és honesto e que aquele é vil, ἂν ψυχήν τις ἐπιδείξῃ πρεσβυτέραν οὖσαν σώματος plat. alguém poderia demonstrar que a alma é mais antiga que o corpo ♦ méd. 3 expor abertamente algo que lhe pertence ou em benefício próprio: ἐκεῖνος ἐμὲ ἐπεδέξατο γυμνήν her. ele [Candaules] me expôs nua 4 fazer demonstração; ostentar; exibir-se: ἐπιδείκνυσθαι τὴν αὑτοῦ δύναμιν and. fazer demonstração de seu poder, ἐπιδείκνυσθαι ὑπερθέων καὶ κρατῶν plat. demonstrar que supera e domina 5 apresentar-se em ou diante de; exibir-se, dat.: ἐπεδείνυτο τοῖς λωποδύταις ar. exibiu-se diante dos ladrões.</p></section></article>\n<article id=\"entry-dgp-15268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεικνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 4029 na letra ε · nº geral 15268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = ἐπιδείκνυμι.</p></section></article>\n<article id=\"entry-dgp-15269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεικτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 4030 na letra ε · nº geral 15269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐπιδείκνυμι.</p></section></article>\n<article id=\"entry-dgp-15270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεικτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 4031 na letra ε · nº geral 15270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feito para mostrar; capaz de mostrar; indicador claro de, gen. 2 feito para ser mostrado; feito para ser exposto: ἐπ. λόγος dem. discurso de aparato, ἐπ. λέξις linguagem conveniente a um discurso de aparato ♦ ὁ ἐπιδεικτικός 3 orador solene ♦ ἡ ἐπιδεικτική 4 arte da demonstração. 〈ἐπιδείκνυμι〉</p></section></article>\n<article id=\"entry-dgp-15271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεικτικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 4032 na letra ε · nº geral 15271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">demonstrativamente; com ostentação.</p></section></article>\n<article id=\"entry-dgp-15272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεῖν1</h1><div class=\"entry-meta\"><span>DGP · ordem 4033 na letra ε · nº geral 15272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. de ἐπιδέω1.</p></section></article>\n<article id=\"entry-dgp-15273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεῖν2</h1><div class=\"entry-meta\"><span>DGP · ordem 4034 na letra ε · nº geral 15273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de ἐφοράω.</p></section></article>\n<article id=\"entry-dgp-15274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδειξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4035 na letra ε · nº geral 15274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de mostrar-se; exibição; aparição 2 exposição; alarde; ostentação 3 exibição oratória; discurso público; leitura pública 4 discurso solene; declamação 5 exemplo; prova. 〈ἐπιδείκνυμι〉</p></section></article>\n<article id=\"entry-dgp-15275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδείπνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4036 na letra ε · nº geral 15275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vem após refeição; que vem na sobremesa. 〈ἐπίδειπνον〉</p></section></article>\n<article id=\"entry-dgp-15276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδειπνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4037 na letra ε · nº geral 15276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. sobremesa. 〈ἐπί, δεῖπνον〉</p></section></article>\n<article id=\"entry-dgp-15277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέκατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4038 na letra ε · nº geral 15277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de dez por cento ♦ τὸ ἐπιδέκατον 2 pagamento de dez por cento; imposto de dez por cento; dízimo. 〈ἐπιδέχομαι〉</p></section></article>\n<article id=\"entry-dgp-15278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 4039 na letra ε · nº geral 15278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de conter 2 capaz de, gen. 〈ἐπιδέχομαι〉</p></section></article>\n<article id=\"entry-dgp-15279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεκτικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 4040 na letra ε · nº geral 15279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo a conter; de modo suficiente.</p></section></article>\n<article id=\"entry-dgp-15280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέμνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4041 na letra ε · nº geral 15280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está na cama. 〈ἐπί, δέμνιον〉</p></section></article>\n<article id=\"entry-dgp-15281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4042 na letra ε · nº geral 15281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. jôn. de ἐπιδείκνυμι.</p></section></article>\n<article id=\"entry-dgp-15282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέξιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4043 na letra ε · nº geral 15282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 favorável; de bom agouro 2 capaz; hábil; apto, para algo, περί ou πρός e ac., ou inf. ♦ ἐπιδέξια adv. 3 à direita 4 da direita para a esquerda. 〈ἐπί, δεξιός〉</p></section></article>\n<article id=\"entry-dgp-15283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεξιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4044 na letra ε · nº geral 15283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destreza; habilidade 2 astúcia; inteligência; tato. 〈ἐπιδέξιος〉</p></section></article>\n<article id=\"entry-dgp-15284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδεξις (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4045 na letra ε · nº geral 15284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐπίδειξις.</p></section></article>\n<article id=\"entry-dgp-15285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4046 na letra ε · nº geral 15285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπιδέω1.</p></section></article>\n<article id=\"entry-dgp-15286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδεσμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4047 na letra ε · nº geral 15286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = ἐπίδεσμος.</p></section></article>\n<article id=\"entry-dgp-15287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίδεσμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4048 na letra ε · nº geral 15287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atadura de curativo. 〈ἐπί, δεσμός〉</p></section></article>\n<article id=\"entry-dgp-15288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεσμοχαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4049 na letra ε · nº geral 15288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amigo das ataduras (gota). 〈ἐπίδεσμος, χαίρω〉</p></section></article>\n<article id=\"entry-dgp-15289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδεσπόζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4050 na letra ε · nº geral 15289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandar; governar; dominar, dat. ou gen.</p></section></article>\n<article id=\"entry-dgp-15290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιδευής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4051 na letra ε · nº geral 15290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que carece de; privado de; necessitado de, gen. 2 defeituoso; inferior em algo, gen., a alguém, gen.: βίης ἐπιδευέες ἀντιθέου Ὀδυσῆος hom. inferiores em força ao divino Odisseu 3 fraco; insuficiente; precário: ἐπιδευέα θέσφατα a.r. oráculos insuficientes, obscuros. 〈ἐπιδεύομαι〉</p></section></article>\n";
